			var pTop []int32 = make([]int32, 1)
			var pWidth []int32 = make([]int32, 1)
			var pHeight []int32 = make([]int32, 1)
			win32.OSMoveMemoryOverload6(pLeft, pxLeft, 4)
			win32.OSMoveMemoryOverload6(pTop, pyTop, 4)
			win32.OSMoveMemoryOverload6(pWidth, pcxWidth, 4)
			win32.OSMoveMemoryOverload6(pHeight, pcyHeight, 4)
