	win32.OSMoveMemoryOverload13(pyTop, []int32{event.Y}, 4)
	win32.OSMoveMemoryOverload13(pcxWidth, []int32{event.Width}, 4)
	win32.OSMoveMemoryOverload13(pcyHeight, []int32{event.Height}, 4)
